<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, shallowRef, watch } from 'vue';
import * as echarts from 'echarts/core';
import { AxisPointerComponent, DataZoomComponent, GridComponent, TooltipComponent } from 'echarts/components';
import { BarChart, LineChart } from 'echarts/charts';
import { CanvasRenderer } from 'echarts/renderers';
import type { ECharts, EChartsCoreOption } from 'echarts/core';
import type { IndexHistoryPoint } from '../types/index';
echarts.use([AxisPointerComponent,DataZoomComponent,GridComponent,TooltipComponent,BarChart,LineChart,CanvasRenderer]);
const props=defineProps<{history:IndexHistoryPoint[];symbol:string}>();
const ranges=[{v:'1m',l:'1月',d:31},{v:'3m',l:'3月',d:93},{v:'1y',l:'1年',d:366},{v:'3y',l:'3年',d:1098},{v:'5y',l:'5年',d:1830},{v:'all',l:'全部',d:0}];
const active=ref('1y'),el=ref<HTMLDivElement|null>(null),chart=shallowRef<ECharts|null>(null);
const visible=computed(()=>{const days=ranges.find(r=>r.v===active.value)?.d??0;if(!days||!props.history.length)return props.history;const end=new Date(props.history.at(-1)!.date);end.setDate(end.getDate()-days);return props.history.filter(p=>new Date(p.date)>=end);});
const usesAmount=computed(()=>visible.value.some(p=>p.amount!==null));
const option=computed<EChartsCoreOption>(()=>({animationDuration:250,axisPointer:{link:[{xAxisIndex:'all'}]},tooltip:{trigger:'axis',confine:true,formatter:(params:unknown)=>tooltip(params)},grid:[{left:58,right:20,top:24,height:'61%'},{left:58,right:20,top:'76%',height:'15%'}],xAxis:[{type:'category',data:visible.value.map(p=>p.date),boundaryGap:false,axisLine:{lineStyle:{color:'#cbd5e1'}},axisTick:{show:false},axisLabel:{color:'#64748b',fontSize:11,hideOverlap:true}},{type:'category',gridIndex:1,data:visible.value.map(p=>p.date),boundaryGap:true,axisLine:{show:false},axisTick:{show:false},axisLabel:{show:false}}],yAxis:[{type:'value',scale:true,axisLabel:{color:'#64748b',fontSize:11,formatter:(v:number)=>number(v)},splitLine:{lineStyle:{color:'#e5e7eb'}}},{type:'value',gridIndex:1,axisLabel:{color:'#94a3b8',fontSize:10,formatter:(v:number)=>compact(v)},splitLine:{show:false}}],dataZoom:[{type:'inside',xAxisIndex:[0,1],filterMode:'none'}],series:[{name:'收盘点位',type:'line',data:visible.value.map(p=>p.close),showSymbol:visible.value.length<=40,symbolSize:5,connectNulls:false,lineStyle:{width:2.5,color:'#2563eb'},itemStyle:{color:'#2563eb'},areaStyle:{color:'rgba(37,99,235,.08)'}},{name:usesAmount.value?'成交额':'成交量',type:'bar',xAxisIndex:1,yAxisIndex:1,data:visible.value.map(p=>usesAmount.value?p.amount:p.volume),itemStyle:{color:'rgba(100,116,139,.42)'},barMaxWidth:8}]}));
watch(option,async v=>{await nextTick();ensure();chart.value?.setOption(v,true)});onMounted(async()=>{await nextTick();ensure();chart.value?.setOption(option.value,true);window.addEventListener('resize',resize)});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);chart.value?.dispose()});
function ensure(){if(!chart.value&&el.value)chart.value=echarts.init(el.value)} function resize(){chart.value?.resize()} function number(v:number|null){return v===null?'-':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(v)} function compact(v:number){return Math.abs(v)>=1e8?`${(v/1e8).toFixed(1)}亿`:Math.abs(v)>=1e4?`${(v/1e4).toFixed(0)}万`:v.toFixed(0)} function percent(v:number|null){return v===null?'-':`${v>=0?'+':''}${v.toFixed(2)}%`}
function tooltip(params:unknown){const a=Array.isArray(params)?params:[params],i=(a[0] as {dataIndex?:number})?.dataIndex,p=typeof i==='number'?visible.value[i]:null;if(!p)return'';const activity=usesAmount.value?p.amount:p.volume;return `<div class="etf-chart-tooltip"><strong>${p.date}</strong><dl><dt>收盘</dt><dd>${number(p.close)}</dd><dt>涨跌幅</dt><dd class="${(p.changePercent??0)>=0?'up':'down'}">${percent(p.changePercent)}</dd><dt>最高 / 最低</dt><dd>${number(p.high)} / ${number(p.low)}</dd><dt>${usesAmount.value?'成交额':'成交量'}</dt><dd>${activity===null?'-':compact(activity)}</dd></dl></div>`}
</script>
<template><section class="etf-price-panel"><header><div><span>历史行情</span><h2>点位与成交</h2></div><div class="etf-range-switch" aria-label="历史行情范围"><button v-for="r in ranges" :key="r.v" type="button" :class="{active:active===r.v}" @click="active=r.v">{{r.l}}</button></div></header><div ref="el" class="etf-price-chart" role="img" :aria-label="`${symbol} 指数历史行情`"></div></section></template>
